const R:&str="/home/ubuntu/src/zopro-perf-work/g2-aos-gather176";const Z:&str="/home/ubuntu/src/zk-tools/zopro";
fn r(p:&str)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn h(b:impl AsRef<[u8]>)->String{format!("{:x}",Sha256::digest(b.as_ref()))}fn hash(p:impl AsRef<Path>)->String{h(fs::read(p).unwrap())}
fn result(n:&str)->Value{let s=fs::read_to_string(r(&format!("capture/{n}/stdout.log"))).unwrap();let v=s.lines().filter_map(|s|s.strip_prefix("RESULT ")).collect::<Vec<_>>();assert_eq!(v.len(),1);serde_json::from_str(v[0]).unwrap()}
fn near(a:f64,b:f64){assert!((a-b).abs()<=1e-12*a.abs().max(b.abs()).max(1.));}
fn stats(mut ratios:Vec<f64>)->(f64,f64,f64,usize){assert_eq!(ratios.len(),15);let wins=ratios.iter().filter(|r|**r<1.).count();ratios.sort_by(f64::total_cmp);(ratios[7],ratios[3],ratios[11],wins)}
fn check(s:&Value,x:(f64,f64,f64,usize)){near(s["median"].as_f64().unwrap(),x.0);near(s["low"].as_f64().unwrap(),x.1);near(s["high"].as_f64().unwrap(),x.2);assert_eq!(s["wins"],x.3);}
fn main(){assert!(!r("review.json").exists());let mut occurrences=0;let mut unique=BTreeMap::new();let mut commands=0;
for (plan,dir,pins)in[("native-plan.json","native","native-pins.json"),("link-plan.json","link-runs","link-pins.json"),("capture-plan.json","capture","capture-pins.json")]{let plan=read(r(plan));let pins=read(r(pins));for(p,sha)in pins.as_object().unwrap(){assert_eq!(hash(p),sha.as_str().unwrap());unique.insert(p.clone(),sha.clone());occurrences+=1;}assert_eq!(read(r(&format!("{dir}/result.json")))["status"],"complete");for step in plan["steps"].as_array().unwrap(){let name=step["name"].as_str().unwrap();let path=r(&format!("{dir}/{name}"));let exit=read(path.join("exit.json"));assert_eq!(exit["success"],true);assert_eq!(exit["returncode"],0);let cmd=read(path.join("command.json"));assert_eq!(&cmd["argv"].as_array().unwrap()[4..],step["argv"].as_array().unwrap());for stream in["stdout","stderr"]{assert_eq!(hash(path.join(format!("{stream}.log"))),exit[format!("{stream}_sha256")].as_str().unwrap());}commands+=1;}}
assert_eq!(commands,323);assert_eq!(occurrences,1909);
let manifest=read(format!("{Z}/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json"));let audit=read(r("source-audit.json"));let suffix=audit["field_lib_suffix"].as_str().unwrap().as_bytes();let mut exact=0;for(p,sha)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(format!("{Z}/{p}")),sha.as_str().unwrap());let mut b=fs::read(r("source").join(p)).unwrap();if h(&b)==sha.as_str().unwrap(){exact+=1;}if p=="crates/zopro-bn254/src/lib.rs"{assert!(b.ends_with(suffix));b.truncate(b.len()-suffix.len());}assert_eq!(h(b),sha.as_str().unwrap());}assert_eq!(exact,175);assert_eq!(fs::read(r("aos_gather.rs")).unwrap(),fs::read(r("source/crates/zopro-bn254/src/aos_gather.rs")).unwrap());
let original=fs::read_to_string("/home/ubuntu/src/zopro-perf-work/g2-blocked-codec176/driver.rs").unwrap();assert_eq!(original,fs::read_to_string(r("driver-original.rs")).unwrap());let mut expected=original;for(a,b)in[("cfg(blocked)","cfg(aos_gather)"),("cfg(not(blocked))","cfg(not(aos_gather))"),("cfg!(blocked)","cfg!(aos_gather)"),("zopro_bn254::blocked_input::Blocked","zopro_bn254::aos_gather::Gather"),("type Input<'a>=Blocked<'a>;","type Input<'a>=Gather<'a>;"),("let input=Blocked::encode(&mut points).unwrap();","let input=Gather::checked(&points).unwrap();"),("\"blocked\":cfg!(aos_gather)","\"direct_AoS_gather\":cfg!(aos_gather)")]{assert!(expected.contains(a));expected=expected.replace(a,b);}assert_eq!(expected,fs::read_to_string(r("driver.rs")).unwrap());
let tests=fs::read_to_string(r("native/gather-tests/stdout.log")).unwrap();assert!(tests.contains("2 passed; 0 failed; 0 ignored; 0 measured; 35 filtered out"));let testerr=fs::read_to_string(r("native/gather-tests/stderr.log")).unwrap();assert!(testerr.contains("AOS_GATHER_COMPONENT_LANES=317184"));assert_eq!(430*4*32+8192*32,317184);
let link=read(r("link-plan.json"));for step in link["steps"].as_array().unwrap(){for flag in["-O","target-cpu=native","lto=fat","codegen-units=1"]{assert!(step["argv"].as_array().unwrap().contains(&json!(flag)));}}
let a=read(r("analysis.json"));let jobs=read(r("jobs.json"));let mut times=BTreeMap::new();let mut groups=0u64;let mut primes=0u64;let mut rows=0;let mut digests=BTreeMap::new();
for j in jobs.as_array().unwrap(){let name=j["name"].as_str().unwrap();let v=result(name);let shape=j["case"]["shape"].as_str().unwrap();let workers=j["case"]["workers"].as_u64().unwrap();let rounds=j["rounds"].as_u64().unwrap();let arm=j["arm"].as_str().unwrap();let meta=read(format!("/home/ubuntu/src/zopro-perf-work/g2-blocked-codec176/private/{shape}.root.json"));assert_eq!(v["arm"],arm);assert_eq!(v["workers"],workers);assert_eq!(v["rounds"],rounds);assert_eq!(v["root_sha256"],meta["file_sha256"]);assert_eq!(v["trace_sha256"],meta["trace_sha256"]);assert_eq!(v["full_groups_per_cycle"],meta["full_groups"]);assert_eq!(v["timed_allocations"],0);assert_eq!(v["independent_scalar_norm_sum_matches"],true);assert_eq!(v["prime_cycles_per_worker"],3);if arm=="frozen"{assert_eq!(v["blocked"],false);}else{assert_eq!(v["direct_AoS_gather"],arm=="on");}
let key=(shape.to_string(),rounds);let digest=digests.entry(key).or_insert_with(||{let mut b=vec![];for row in meta["scalar_norm_sum_raw_words"].as_array().unwrap(){let raw:[u64;4]=serde_json::from_value(row.clone()).unwrap();let value=Fq::from_montgomery(raw)*Fq::from(rounds);for word in value.to_canonical(){b.extend_from_slice(&word.to_le_bytes());}}h(b)});assert_eq!(v["output_sha256"],digest.as_str());let wrows=v["worker_rows"].as_array().unwrap();assert_eq!(wrows.len()as u64,workers);let mut tids=BTreeSet::new();for(i,w)in wrows.iter().enumerate(){assert_eq!(w["worker"],i);assert_eq!(w["cpu"],if workers==1{2}else{i});assert!(tids.insert(w["tid"].as_u64().unwrap()));assert_eq!(w["digest"],digest.as_str());assert!(w["elapsed_ns"].as_u64().unwrap()<=v["wall_ns"].as_u64().unwrap());}
groups+=workers*rounds*meta["full_groups"].as_u64().unwrap();primes+=workers*3*meta["full_groups"].as_u64().unwrap();if j["panel"]=="latency"{assert!(times.insert((j["case"]["name"].as_str().unwrap().to_string(),arm.to_string(),j["block"].as_u64().unwrap()as usize),v["wall_ns"].as_u64().unwrap()as f64/rounds as f64).is_none());}rows+=1;}
assert_eq!(rows,296);assert_eq!(times.len(),270);assert_eq!(a["measured_full8_coordinate_groups"],groups);assert_eq!(a["primed_full8_coordinate_groups"],primes);
let get=|c:&str,arm:&str,b:usize|times[&(c.to_string(),arm.to_string(),b)];let cases=read(r("cases.json"));let mut fails=BTreeSet::new();let mut distributions=0;
for c in cases.as_array().unwrap(){let name=c["name"].as_str().unwrap();for arm in["frozen","off","on"]{let(mut vals)=(0..15).map(|b|get(name,arm,b)).collect::<Vec<_>>();vals.sort_by(f64::total_cmp);near(a["medians_ms_per_full_cycle_wave"][format!("{name}/{arm}")].as_f64().unwrap(),vals[7]/1e6);}for(n,d)in[("off","frozen"),("on","frozen"),("on","off")]{let key=format!("{name}/{n}/{d}");let x=stats((0..15).map(|b|get(name,n,b)/get(name,d,b)).collect());check(&a["comparisons"][&key]["paired"],x);let pass=x.2<=1.03&&(n!="off"||x.1>=1./1.03);assert_eq!(a["comparisons"][&key]["passed"],pass);if !pass{fails.insert(key);}distributions+=1;}}
for group in["all6","logical32_2"]{let selected=cases.as_array().unwrap().iter().filter(|c|group=="all6"||c["workers"]==32).collect::<Vec<_>>();for d in["frozen","off"]{let key=format!("{group}/on/{d}");let x=stats((0..15).map(|b|(selected.iter().map(|c|{let n=c["name"].as_str().unwrap();(get(n,"on",b)/get(n,d,b)).ln()}).sum::<f64>()/selected.len()as f64).exp()).collect());check(&a["aggregates"][&key]["paired"],x);let pass=x.2<1.&&x.3>=10;assert_eq!(a["aggregates"][&key]["passed"],pass);if !pass{fails.insert(format!("{key}/gain"));}distributions+=1;}}
assert_eq!(fails,a["failed_checks"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_string()).collect());assert_eq!(fails.len(),16);assert_eq!(distributions,22);assert_eq!(a["codec_gate_passed"],false);
let mut samples=0;let mut profiles=vec![];for p in a["profiles"].as_array().unwrap(){let name=p["job"].as_str().unwrap();let loss=read(r(&format!("capture/loss-{name}/stdout.log")));assert_eq!(loss["zero_lost"],true);assert!(loss["records"].as_array().unwrap().is_empty());let decoded=fs::read_to_string(r(&format!("capture/decode-{name}/stdout.log"))).unwrap();let pid=p["pid"].as_u64().unwrap()as u32;let mut count=0;let mut unknown=0;let mut seen=BTreeSet::new();for l in decoded.lines(){if l.trim().is_empty()||l.trim_start().starts_with('#'){continue;}let f=l.split_whitespace().collect::<Vec<_>>();assert!(f.len()>=6);let(ids,tids)=f[0].split_once('/').unwrap();let id=ids.parse::<u32>().unwrap();assert_eq!(id,pid);let tid=tids.parse::<u32>().unwrap();let cpu=f[1].trim_matches(['[',']']).parse::<u32>().unwrap();assert_eq!(f[3].parse::<u64>().unwrap(),16000000);if let Some(c)=p["worker_TID_CPU_pairs"].get(tid.to_string()){assert_eq!(cpu,c.as_u64().unwrap()as u32);seen.insert(tid);}if f[5..].join(" ").starts_with("[unknown]"){unknown+=1;}count+=1;}assert_eq!(p["samples"],count);near(p["unknown_fraction"].as_f64().unwrap(),unknown as f64/count as f64);assert_eq!(seen.len(),p["worker_TID_CPU_pairs"].as_object().unwrap().len());assert!(count>=1000&&unknown as f64/count as f64<=0.05);assert_eq!(p["qualified"],true);samples+=count;profiles.push(json!({"name":name,"samples":count,"all_workers_observed":true,"zero_LOST":true}));}
for panel in a["counters"].as_array().unwrap(){assert_eq!(panel["qualified"],true);let path=panel["job"]["data"].as_str().unwrap();let mut count=0;for l in fs::read_to_string(path).unwrap().lines(){let f=l.split(';').collect::<Vec<_>>();if f.len()>5&&f[2].ends_with(":u"){let value=f[0].parse::<f64>().unwrap();assert!(value>0.);assert!(f[4].parse::<f64>().unwrap()>=99.9);count+=1;}}assert_eq!(count,4);}
let ledger=read("/home/ubuntu/src/zopro-perf-work/coarse-proof-phase-universal176/proof-sha256-after.json");assert_eq!(ledger.as_array().unwrap().len(),30846);
let out=json!({"review_passed":true,"scope":"independent receipts/source recovery, raw timing statistics, scalar digests and decoded profile ownership; not formal machine-code or complete curve/prover qualification","unique_pins":unique.len(),"pin_occurrences":occurrences,"workflow_commands":commands,"native_tests":2,"inherited_field_tests_filtered":35,"component_lanes_checked":317184,"originals_exact":175,"all176recover":true,"production_originals_exact":176,"caller_rows":rows,"latency_rows":270,"paired_distributions_recomputed":distributions,"failed_checks_reproduced":fails,"all_six_calibrations_pass":true,"profiles":profiles,"profile_samples":samples,"PMU_panels_qualified":4,"measured_groups":groups,"primed_groups":primes,"gate_passed":false,"adopted":false,"new_proofs":0,"ledger":30846,"goal_status":"active/unmet0/8"});fs::write(r("review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Review PASS{}pins/{}occurrences/{}commands/296callers/22distributions/{}samples;16failedchecks reproduced",unique.len(),occurrences,commands,samples);}
